const fs = require('fs');
const path = require('path');

const allQuestions = [];
const seenQuestions = new Set();

function addQ(id, grade, topic, level, question, options, correctAnswer, explanation) {
  if (seenQuestions.has(question)) {
    throw new Error(`Duplicate question in Pendidikan Pancasila: "${question}"`);
  }
  seenQuestions.add(question);
  allQuestions.push({
    id,
    grade,
    subject: "pancasila",
    topic,
    level,
    question,
    options,
    correctAnswer,
    explanation
  });
}

addQ("pan-k1-m01", 1, "Lambang Negara", "mudah", "Lambang negara Republik Indonesia adalah burung ...", ["Garuda", "Rajawali", "Merpati", "Elang"], 0, "Burung Garuda Pancasila adalah lambang negara resmi Indonesia.");
