addQ("pan-k1-m03", 1, "Simbol Sila Ke-2", "mudah", "Simbol rantai emas melambangkan sila Pancasila yang ke- ...", ["Dua", "Satu", "Tiga", "Empat"], 0, "Rantai emas melambangkan sila ke-2 Kemanusiaan yang adil dan beradab.");
addQ("pan-k1-m04", 1, "Simbol Sila Ke-3", "mudah", "Pohon beringin adalah simbol sila Pancasila yang ke- ...", ["Tiga", "Satu", "Dua", "Lima"], 0, "Pohon beringin adalah lambang sila ke-3 Persatuan Indonesia.");
addQ("pan-k1-m05", 1, "Simbol Sila Ke-4", "mudah", "Kepala banteng merupakan simbol sila Pancasila yang ke- ...", ["Empat", "Tiga", "Dua", "Satu"], 0, "Kepala banteng melambangkan sila ke-4.");
addQ("pan-k1-m06", 1, "Simbol Sila Ke-5", "mudah", "Padi dan kapas adalah simbol sila Pancasila yang ke- ...", ["Lima", "Empat", "Tiga", "Dua"], 0, "Padi dan kapas melambangkan sila ke-5 Keadilan sosial bagi seluruh rakyat Indonesia.");
addQ("pan-k1-m07", 1, "Warna Bendera RI", "mudah", "Bendera kebangsaan negara Indonesia berwarna ...", ["Merah dan Putih", "Merah dan Kuning", "Biru dan Putih", "Hijau dan Putih"], 0, "Bendera Indonesia adalah Sang Merah Putih.");
addQ("pan-k1-m08", 1, "Lagu Kebangsaan", "mudah", "Lagu kebangsaan negara kita Republik Indonesia adalah ...", ["Indonesia Raya", "Garuda Pancasila", "Hari Merdeka", "Halo-Halo Bandung"], 0, "Indonesia Raya ciptaan W.R. Soepratman adalah lagu kebangsaan.");
addQ("pan-k1-m09", 1, "Aturan Kebersihan Rumah", "mudah", "Tempat membuang sampah yang benar adalah di ...", ["Tempat sampah", "Lantai kamar", "Bawah kasur", "Halaman tetangga"], 0, "Sampah harus dibuang pada tempat sampah agar lingkungan bersih.");
addQ("pan-k1-m10", 1, "Sikap Berdoa", "mudah", "Sebelum makan dan belajar, kita sebaiknya membiasakan diri untuk ...", ["Berdoa", "Bermain HP", "Bernyanyi keras", "Tidur"], 0, "Berdoa sebelum beraktivitas adalah wujud syukur kepada Tuhan.");

addQ("pan-k1-s01", 1, "Arti Warna Merah Bendera", "sedang", "Warna merah pada bendera Merah Putih memiliki arti ...", ["Berani", "Suci", "Damai", "Subur"], 0, "Merah melambangkan keberanian bangsa Indonesia.");
addQ("pan-k1-s02", 1, "Arti Warna Putih Bendera", "sedang", "Warna putih pada bendera Merah Putih memiliki arti ...", ["Suci", "Berani", "Kaya", "Mewah"], 0, "Putih melambangkan kesucian hati dan niat luhur bangsa.");
addQ("pan-k1-s03", 1, "Aturan Bangun Pagi", "sedang", "Setelah bangun tidur di pagi hari, tindakan yang baik untuk merapikan tempat tidur adalah ...", ["Melipat selimut dan menata bantal", "Langsung bermain game", "Membiarkan kasur berantakan", "Kembali tidur siang"], 0, "Merapikan tempat tidur melatih disiplin dan kemandirian sejak dini.");
addQ("pan-k1-s04", 1, "Aturan Berangkat Sekolah", "sedang", "Sebelum berangkat ke sekolah, kita harus berpamitan kepada orang tua dengan cara ...", ["Mencium tangan dan mengucapkan salam", "Pergi diam-diam", "Berteriak dari luar", "Menangis"], 0, "Berpamitan dan bersalaman menunjukkan rasa hormat dan bakti kepada orang tua.");
addQ("pan-k1-s05", 1, "Sikap Saat Upacara Bendera", "sedang", "Saat pengibaran bendera Merah Putih berlangsung pada upacara bendera, sikap kita yang benar adalah ...", ["Berdiri tegak dan memberi hormat khidmat", "Bercanda dengan teman sebangku", "Duduk bersila santai", "Makan permen"], 0, "Sikap sempurna dan hormat menunjukkan rasa cinta tanah air.");
addQ("pan-k1-s06", 1, "Sikap Tertib di Kelas", "sedang", "Ketika guru sedang menerangkan pelajaran di depan kelas, sikap siswa yang tertib adalah ...", ["Mendengarkan dengan sungguh-sungguh", "Mengobrol sendiri", "Tidur di atas meja", "Berlari-larian"], 0, "Mendengarkan guru adalah bentuk kepatuhan terhadap aturan belajar.");
addQ("pan-k1-s07", 1, "Tolong-menolong Teman", "sedang", "Jika pensil teman patah dan ia tidak membawa rautan, sikap baik kita adalah ...", ["Meminjamkan rautan atau pensil cadangan", "Menertawakannya", "Menyuruhnya pulang", "Menyembunyikan pensil kita"], 0, "Saling tolong-menolong adalah wujud kerukunan antarteman.");
addQ("pan-k1-s08", 1, "Meminta Izin", "sedang", "Jika kita ingin meminjam buku gambar milik teman, sikap yang sopan adalah ...", ["Meminta izin terlebih dahulu dengan ramah", "Mengambil diam-diam", "Merebut secara paksa", "Merobeknya"], 0, "Meminta izin adalah wujud menghargai hak milik orang lain.");
addQ("pan-k1-s09", 1, "Mengakui Kesalahan", "sedang", "Jika kita tidak sengaja menyenggol tempat minum teman hingga tumpah, kita harus segera ...", ["Meminta maaf dan membantu mengelap airnya", "Menyalahkan orang lain", "Pura-pura tidak tahu", "Marah-marah"], 0, "Meminta maaf dan bertanggung jawab mencerminkan anak berakhlak mulia.");
addQ("pan-k1-s10", 1, "Menghargai Perbedaan Fisik", "sedang", "Teman sekelas kita memiliki rambut keriting dan kulit sawo matang, sikap kita terhadapnya adalah ...", ["Tetap berteman akrab tanpa mengejek", "Menjauhinya", "Mengolok-olok rambutnya", "Menyuruhnya pindah"], 0, "Setiap orang diciptakan unik oleh Tuhan dan harus dihargai.");
addQ("pan-k1-s11", 1, "Gotong Royong Kelas 1", "sedang", "Membersihkan ruang kelas bersama seluruh regu piket membuat pekerjaan menjadi terasa ...", ["Lebih ringan dan cepat selesai", "Lebih berat", "Sangat membosankan", "Lama sekali"], 0, "Gotong royong meringankan beban pekerjaan dan mempererat persahabatan.");
addQ("pan-k1-s12", 1, "Sopan Santun Bertemu Guru", "sedang", "Saat berpapasan dengan guru di koridor sekolah, sikap sopan kita adalah ...", ["Menyapa dengan senyum dan mengucapkan salam", "Membuang muka", "Lari bersembunyi", "Berdiam diri"], 0, "Memberi salam kepada guru adalah adab kesantunan siswa.");
addQ("pan-k1-s13", 1, "Membiasakan Antre", "sedang", "Ketika hendak membeli makanan di kantin sekolah yang ramai, kita harus membiasakan diri untuk ...", ["Mengantre tertib sesuai giliran", "Menyerobot antrean teman", "Mendorong dari belakang", "Berteriak-teriak"], 0, "Mengantre melatih kesabaran dan keadilan menghormati orang lain.");
addQ("pan-k1-s14", 1, "Kerukunan di Rumah", "sedang", "Jika adik ingin bermain mainan balok bersama kita di ruang tengah, sikap kakak yang baik adalah ...", ["Mengajak adik bermain bersama dengan rukun", "Mengusir adik ke luar", "Merampas semua mainan", "Menangis keras"], 0, "Rukun dengan saudara menciptakan suasana rumah yang bahagia.");
addQ("pan-k1-s15", 1, "Berterima Kasih", "sedang", "Setelah diberi hadiah buku cerita bergambar oleh paman, ucapan yang wajib kita sampaikan adalah ...", ["Terima kasih banyak, Paman", "Buku ini jelek sekali", "Minta uang saja", "Diam saja"], 0, "Mengucapkan terima kasih adalah adab menghargai kebaikan sesama.");
addQ("pan-k1-s16", 1, "Menjaga Ketertiban Malam", "sedang", "Aturan di rumah saat malam hari menjelang waktu istirahat tidur adalah ...", ["Tidur tepat waktu tidak larut malam", "Menyetel televisi sangat keras", "Bermain bola di dalam rumah", "Berteriak kencang"], 0, "Tidur cukup menjaga kesehatan tubuh agar bugar di pagi hari.");
addQ("pan-k1-s17", 1, "Makan Bersama Keluarga", "sedang", "Adab sopan saat makan bersama keluarga di meja makan adalah ...", ["Duduk tenang dan tidak berbicara saat mulut penuh", "Bersendawa keras sengaja", "Melempar sendok", "Makan sambil berlari"], 0, "Tata tertib makan menjaga kenyamanan dan kesantunan bersama.");
addQ("pan-k1-s18", 1, "Menjaga Kebersihan Tubuh", "sedang", "Aturan menjaga kebersihan diri sendiri setelah selesai berolahraga di lapangan adalah ...", ["Mencuci tangan, kaki, atau mandi bersih", "Langsung tidur memakai baju kotor", "Mengusap keringat ke sofa", "Bermain lumpur lagi"], 0, "Menjaga kebersihan diri melindungi tubuh dari kuman dan penyakit.");
addQ("pan-k1-s19", 1, "Semboyan Bangsa", "sedang", "Pita yang dicengkeram oleh kedua kaki burung Garuda bertuliskan semboyan ...", ["Bhinneka Tunggal Ika", "Tut Wuri Handayani", "Pancasila Sakti", "Merdeka atau Mati"], 0, "Bhinneka Tunggal Ika bermakna berbeda-beda tetapi tetap satu.");
addQ("pan-k1-s20", 1, "Menghargai Kesukaan Teman", "sedang", "Dodi suka menggambar mobil, sedangkan Edo suka menggambar rumah. Sikap Dodi dan Edo sebaiknya ...", ["Saling memuji dan menghargai karya masing-masing", "Saling mengejek gambar", "Merusak buku gambar teman", "Memaksa teman menggambar yang sama"], 0, "Perbedaan kesukaan harus disikapi dengan saling menghargai.");

addQ("pan-k1-u01", 1, "Penerapan Sila Ke-1 di Kelas 1", "sulit", "Siti beragama Islam dan membaca doa sebelum makan, sedangkan Maria beragama Kristen dan berdoa menurut agamanya. Sikap mereka yang tepat adalah ...", ["Saling menghormati cara berdoa masing-masing", "Melarang teman berdoa", "Menertawakan doa teman", "Memaksa teman mengikuti cara berdoanya"], 0, "Sila pertama mengajarkan saling menghormati pemeluk agama yang berbeda.");
addQ("pan-k1-u02", 1, "Penerapan Sila Ke-2 di Lingkungan Bermain", "sulit", "Saat bermain kejar-kejaran di taman, Budi tersandung akar pohon dan lututnya terluka. Sikap teman-teman yang sesuai sila kedua adalah ...", ["Segera menolong Budi berdiri dan mengobati lukanya", "Menertawakan Budi yang jatuh", "Meninggalkan Budi sendirian", "Terus berlari tidak peduli"], 0, "Menolong orang yang tertimpa musibah merupakan wujud rasa kemanusiaan.");
addQ("pan-k1-u03", 1, "Penerapan Sila Ke-3 dalam Keberagaman Suku", "sulit", "Di kelas 1 ada murid dari suku Jawa, Sunda, Batak, dan Madura. Agar kelas selalu rukun bersatu, mereka harus ...", ["Bermain bersama tanpa membeda-bedakan asal suku", "Hanya berteman dengan sesuku", "Mengejek logat bicara teman", "Membentuk kelompok sendiri-sendiri"], 0, "Sila ke-3 mengajarkan persatuan di atas segala perbedaan suku bangsa.");
addQ("pan-k1-u04", 1, "Musyawarah Memilih Permainan", "sulit", "Anak-anak kelas 1 ingin bermain saat istirahat, sebagian ingin petak umpet dan sebagian ingin lompat tali. Cara terbaik menyelesaikan perbedaan ini adalah ...", ["Bermusyawarah menentukan giliran bermain secara adil", "Berkelahi memaksakan kehendak", "Menangis dan melapor ke kepala sekolah", "Pulang ke rumah"], 0, "Musyawarah mencapai mufakat adalah cerminan sila keempat.");
addQ("pan-k1-u05", 1, "Keadilan Membagi Tugas Piket", "sulit", "Ketua kelas membagi tugas piket kebersihan kelas: ada yang menyapu, menghapus papan tulis, dan membuang sampah. Semua siswa mendapatkan tugas. Tindakan ketua kelas mencerminkan sila ke- ...", ["Lima", "Dua", "Satu", "Tiga"], 0, "Pembagian tugas secara adil dan merata mencerminkan sila kelima.");
addQ("pan-k1-u06", 1, "Perbedaan Aturan di Rumah dan di Sekolah", "sulit", "Contoh aturan yang berlaku khusus saat kita berada di lingkungan sekolah adalah ...", ["Memakai seragam sekolah dan masuk kelas sebelum bel berbunyi", "Membantu ibu mencuci piring", "Merapikan tempat tidur sendiri", "Mencuci pakaian sendiri"], 0, "Memakai seragam dan hadir tepat waktu saat bel adalah tata tertib sekolah.");
addQ("pan-k1-u07", 1, "Konsekuensi Melanggar Aturan Kelas", "sulit", "Jika seorang murid mencoret-coret dinding ruang kelas dengan krayon, akibat yang terjadi adalah ...", ["Dinding menjadi kotor rusak dan kelas menjadi tidak nyaman", "Kelas bertambah rapi", "Guru memberikan hadiah", "Dinding menjadi bersih"], 0, "Melanggar aturan merusak kenyamanan lingkungan belajar bersama.");
addQ("pan-k1-u08", 1, "Manfaat Menaati Aturan Rumah", "sulit", "Jika setiap anggota keluarga menaati aturan meletakkan barang pada tempatnya setelah digunakan, maka suasana rumah akan ...", ["Selalu rapi, bersih, dan barang mudah dicari", "Sangat sempit dan pengap", "Penuh sampah", "Menjadi sarang nyamuk"], 0, "Disiplin menaati aturan membuat rumah tertata rapi dan tenteram.");
addQ("pan-k1-u09", 1, "Makna Jumlah Bulu Sayap Garuda", "sulit", "Jumlah helai bulu pada masing-masing sayap burung Garuda Pancasila melambangkan tanggal kemerdekaan Indonesia yaitu ...", ["17 helai", "8 helai", "45 helai", "19 helai"], 0, "Sayap Garuda memiliki 17 helai bulu melambangkan tanggal 17 Agustus.");
addQ("pan-k1-u10", 1, "Makna Bulu Ekor Garuda", "sulit", "Jumlah helai bulu pada ekor burung Garuda melambangkan bulan kemerdekaan (Agustus) yaitu sebanyak ...", ["8 helai", "17 helai", "45 helai", "19 helai"], 0, "Bulu ekor berjumlah 8 helai melambangkan bulan ke-8 (Agustus).");
addQ("pan-k1-u11", 1, "Makna Bulu Leher Garuda", "sulit", "Jumlah bulu pada leher burung Garuda melambangkan dua angka terakhir tahun kemerdekaan 1945 yaitu ...", ["45 helai", "17 helai", "8 helai", "19 helai"], 0, "Bulu leher berjumlah 45 helai melambangkan tahun 1945.");
addQ("pan-k1-u12", 1, "Menghargai Bahasa Ibu Teman", "sulit", "Udin baru pindah dari desa dan bicaranya terkadang menggunakan bahasa daerah asalnya. Sikap teman sekelas yang bijak adalah ...", ["Mendengarkan dengan ramah dan membantunya belajar bahasa Indonesia", "Menertawakannya beramai-ramai", "Menyuruhnya diam tidak boleh bicara", "Menjauhi Udin"], 0, "Menghargai bahasa daerah teman memupuk kerukunan dan rasa persaudaraan.");
addQ("pan-k1-u13", 1, "Tanggung Jawab Menjaga Fasilitas Bersama", "sulit", "Buku dongeng di pojok baca kelas robek karena tidak sengaja terinjak. Tindakan terpuji yang sebaiknya dilakukan adalah ...", ["Segera memperbaiki dengan lem/selotip dan memberitahu guru", "Menyembunyikan buku di kolong meja", "Menyalahkan orang lain", "Meninggalkannya begitu saja"], 0, "Merawat fasilitas bersama merupakan tanggung jawab seluruh warga kelas.");
addQ("pan-k1-u14", 1, "Perilaku Rukun Antartetangga", "sulit", "Ketika tetangga sebelah rumah sedang merayakan hari raya keagamaan mereka, sikap keluarga kita yang baik adalah ...", ["Memberikan ucapan selamat dan menjaga ketenangan lingkungan sekitar", "Menyetel musik keras-keras", "Melempar petasan ke halamannya", "Menutup pintu rapat dengan marah"], 0, "Toleransi beragama menciptakan kedamaian dalam bertetangga.");
addQ("pan-k1-u15", 1, "Mengantre Saat Mencuci Tangan", "sulit", "Setelah bermain tanah di halaman sekolah, anak-anak berbaris rapi di wastafel. Jika ada murid yang memotong barisan di depan, sikap yang benar adalah ...", ["Mengingatkannya dengan sopan agar berbaris di belakang sesuai urutan", "Mendorongnya hingga jatuh", "Mengajaknya berkelahi", "Ikut-ikutan menyerobot"], 0, "Mengingatkan dengan santun mendidik kedisiplinan tanpa kekerasan.");
addQ("pan-k1-u16", 1, "Kejujuran Menemukan Barang", "sulit", "Rani menemukan uang lima ribu rupiah terjatuh di koridor sekolah. Tindakan jujur yang sesuai nilai Pancasila adalah ...", ["Menyerahkan uang tersebut kepada guru piket untuk diumumkan pemiliknya", "Memasukkannya ke saku dan membeli es krim", "Membagikan uang itu kepada teman dekatnya", "Membuangnya ke selokan"], 0, "Kejujuran adalah fondasi moral pengamalan nilai-nilai Pancasila.");
addQ("pan-k1-u17", 1, "Adab Masuk Rumah Orang Lain", "sulit", "Saat kita hendak bermain ke rumah teman, tata krama bertamu yang baik adalah ...", ["Mengetuk pintu perlahan dan mengucapkan salam", "Langsung menerobos masuk ke kamar tidur", "Berteriak kencang dari luar jendela", "Membuka kulkas pemilik rumah"], 0, "Mengetuk pintu dan mengucap salam adalah adab kesopanan bertamu.");
addQ("pan-k1-u18", 1, "Membantu Anggota Keluarga di Rumah", "sulit", "Ibu sedang sibuk mencuci piring di dapur sementara adik menangis di ruang keluarga. Tindakan terpuji yang dapat dilakukan anak kelas 1 adalah ...", ["Menghibur adik dan mengajaknya bermain mainan dengan tenang", "Ikut menangis bersama adik", "Menyuruh adik diam dengan membentak", "Pergi keluar rumah"], 0, "Membantu ibu menjaga adik melatih empati dan kepedulian keluarga.");
addQ("pan-k1-u19", 1, "Sikap Rendah Hati Saat Berprestasi", "sulit", "Ahmad memenangkan lomba mewarnai tingkat kelas 1. Sikap Ahmad kepada teman-teman lainnya sebaiknya ...", ["Tetap rendah hati dan menyemangati teman-teman untuk terus berlatih", "Mengejek karya teman-teman yang belum juara", "Menjadi sombong dan tidak mau berteman", "Memamerkan piala sambil mencela orang lain"], 0, "Rendah hati mencerminkan budi pekerti luhur.");
addQ("pan-k1-u20", 1, "Penyebab Terjadinya Perselisihan", "sulit", "Pertengkaran saat bermain bersama di taman sekolah biasanya timbul karena sikap ...", ["Mau menang sendiri dan tidak mau menaati aturan permainan", "Saling mengalah dan berbagi giliran", "Mematuhi wasit dengan tertib", "Saling memaafkan"], 0, "Egois dan curang merusak keharmonisan bermain.");
addQ("pan-k1-u21", 1, "Menghargai Makanan Tradisional", "sulit", "Teman kita membawa bekal kue tradisional lemper, sedangkan kita membawa roti keju. Sikap yang mencerminkan cinta budaya bangsa adalah ...", ["Menghargai bekal teman dan bersedia mencicipi kelezatan kue tradisional", "Menghina kue tradisional terlihat kuno", "Membuang bekal teman", "Menyuruh teman membeli roti"], 0, "Menghargai makanan tradisional memupuk rasa bangga pada budaya nusantara.");
addQ("pan-k1-u22", 1, "Mematikan Lampu Menghemat Energi", "sulit", "Selesai belajar malam hari di meja belajar, kita membiasakan mematikan lampu meja. Tindakan ini mencerminkan sikap ...", ["Hemat dan bijaksana menggunakan fasilitas", "Pelit dan kikir", "Takut gelap", "Malas belajar"], 0, "Menghemat energi adalah wujud tanggung jawab menjaga lingkungan.");
addQ("pan-k1-u23", 1, "Menjaga Rahasia / Kepercayaan Teman", "sulit", "Teman bercerita bahwa ia sedih karena kucing kesayangannya hilang dan berpesan agar tidak ditertawakan. Sikap kita adalah ...", ["Menghiburnya dan menjaga perasaan teman dengan baik", "Menceritakannya kepada semua orang untuk ditertawakan", "Mengejek kucingnya", "Menambah kesedihannya"], 0, "Empati dan menjaga kepercayaan adalah dasar persahabatan yang tulus.");
addQ("pan-k1-u24", 1, "Merawat Tanaman Sekolah", "sulit", "Di taman depan kelas terdapat pot bunga yang daunnya mulai layu. Sikap regu piket kelas 1 adalah ...", ["Menyiram tanaman dengan air secara teratur", "Mencabut bunga-bunga sampai gundul", "Menginjak-injak pot", "Membiarkannya mati kekeringan"], 0, "Menyayangi tanaman lingkungan sekolah adalah wujud syukur pada alam ciptaan Tuhan.");
addQ("pan-k1-u25", 1, "Simbol Padi dan Kapas Kesejahteraan", "sulit", "Padi melambangkan makanan pokok (pangan), sedangkan kapas melambangkan bahan pakaian (sandang). Keduanya melambangkan kebutuhan pokok untuk mewujudkan ...", ["Kemakmuran dan kesejahteraan rakyat", "Kemewahan para pejabat", "Kekuatan perang", "Kemenangan olahraga"], 0, "Pangan dan sandang adalah syarat utama kemakmuran bagi seluruh rakyat.");
addQ("pan-k1-u26", 1, "Menjaga Kerapian Seragam", "sulit", "Aturan memakai seragam sekolah dengan baju dimasukkan rapi dan bersepatu hitam bertujuan melatih murid untuk ...", ["Disiplin, tertib, dan berpenampilan pantas", "Terlihat paling mahal dari teman", "Bisa pamer pakaian", "Bebas berbuat semaunya"], 0, "Seragam sekolah menanamkan kedisiplinan dan rasa kesetaraan antarsiswa.");
addQ("pan-k1-u27", 1, "Kerja Sama Membersihkan Meja", "sulit", "Sebelum bel pulang berbunyi, guru meminta anak-anak merapikan bangku masing-masing. Manfaat kerja sama ini adalah ...", ["Ruang kelas menjadi rapi dan siap digunakan belajar esok hari", "Guru menjadi marah", "Waktu pulang menjadi tertunda semalaman", "Buku-buku menjadi hilang"], 0, "Ketertiban bersama memelihara kenyamanan kelas berkelanjutan.");
addQ("pan-k1-u28", 1, "Menghargai Guru Pengganti", "sulit", "Saat guru kelas berhalangan hadir dan digantikan oleh guru lain, sikap murid di dalam kelas sebaiknya ...", ["Tetap tertib belajar dan patuh menghormati guru pengganti tersebut", "Membuat gaduh dan bernyanyi keras", "Keluar dari kelas tanpa izin", "Tidak mau mengerjakan tugas"], 0, "Setiap guru berhak dihormati dengan sikap santun dan patuh.");
addQ("pan-k1-u29", 1, "Menyanyikan Lagu Indonesia Raya", "sulit", "Saat menyanyikan lagu Indonesia Raya di lapangan sekolah, kita tidak boleh ...", ["Bercanda, mengunyah permen, atau menoleh ke kanan dan ke kiri", "Berdiri tegak", "Memandang bendera Merah Putih", "Bernyanyi dengan suara tegas"], 0, "Menyanyikan lagu kebangsaan menuntut ketegasan, rasa hormat, dan kekhidmatan penuh.");
addQ("pan-k1-u30", 1, "Toleransi Tempat Ibadah", "sulit", "Ketika melewati rumah ibadah umat lain (seperti masjid, gereja, pura, vihara, kelenteng), sikap kita yang santun adalah ...", ["Tidak membuat keributan gaduh dan menjaga ketenangan", "Membunyikan klakson keras-keras", "Melempar batu ke pagar", "Berteriak mengejek"], 0, "Menghormati kesucian rumah ibadah orang lain adalah pilar kerukunan hidup berbangsa.");

