addQ("pan-k2-m01", 2, "Bunyi Sila Ke-1", "mudah", "Bunyi sila pertama Pancasila adalah ...", ["Ketuhanan Yang Maha Esa", "Kemanusiaan yang adil dan beradab", "Persatuan Indonesia", "Keadilan sosial bagi seluruh rakyat Indonesia"], 0, "Sila pertama berbunyi: Ketuhanan Yang Maha Esa.");
addQ("pan-k2-m02", 2, "Bunyi Sila Ke-2", "mudah", "Bunyi sila kedua Pancasila adalah ...", ["Kemanusiaan yang adil dan beradab", "Ketuhanan Yang Maha Esa", "Persatuan Indonesia", "Kerakyatan yang dipimpin oleh hikmat kebijaksanaan"], 0, "Sila kedua berbunyi: Kemanusiaan yang adil dan beradab.");
addQ("pan-k2-m03", 2, "Bunyi Sila Ke-3", "mudah", "Bunyi sila ketiga Pancasila adalah ...", ["Persatuan Indonesia", "Keadilan sosial", "Ketuhanan Yang Maha Esa", "Kemanusiaan yang adil dan beradab"], 0, "Sila ketiga berbunyi: Persatuan Indonesia.");
addQ("pan-k2-m04", 2, "Bunyi Sila Ke-4", "mudah", "Sila keempat Pancasila berbunyi: Kerakyatan yang dipimpin oleh hikmat kebijaksanaan dalam permusyawaratan / ...", ["Perwakilan", "Keadilan", "Persatuan", "Kemerdekaan"], 0, "Kelanjutan bunyi sila ke-4 adalah 'perwakilan'.");
addQ("pan-k2-m05", 2, "Bunyi Sila Ke-5", "mudah", "Bunyi sila kelima Pancasila adalah ...", ["Keadilan sosial bagi seluruh rakyat Indonesia", "Ketuhanan Yang Maha Esa", "Persatuan Indonesia", "Kemanusiaan yang adil"], 0, "Sila kelima berbunyi: Keadilan sosial bagi seluruh rakyat Indonesia.");
addQ("pan-k2-m06", 2, "Agama Resmi di Indonesia", "mudah", "Negara Indonesia mengakui keberagaman agama. Jumlah agama resmi yang diakui pemerintah adalah ...", ["Enam", "Dua", "Tiga", "Sepuluh"], 0, "Ada 6 agama resmi: Islam, Kristen Protestan, Katolik, Hindu, Buddha, dan Khonghucu.");
addQ("pan-k2-m07", 2, "Tempat Ibadah Umat Islam", "mudah", "Tempat ibadah resmi bagi pemeluk agama Islam adalah ...", ["Masjid", "Gereja", "Pura", "Vihara"], 0, "Masjid adalah rumah ibadah umat Islam.");
addQ("pan-k2-m08", 2, "Tempat Ibadah Umat Kristen", "mudah", "Tempat ibadah bagi pemeluk agama Kristen dan Katolik adalah ...", ["Gereja", "Masjid", "Pura", "Kelenteng"], 0, "Gereja adalah rumah ibadah umat Kristiani.");
addQ("pan-k2-m09", 2, "Tempat Ibadah Umat Hindu", "mudah", "Tempat ibadah bagi pemeluk agama Hindu adalah ...", ["Pura", "Masjid", "Gereja", "Vihara"], 0, "Pura adalah rumah ibadah pemeluk agama Hindu.");
addQ("pan-k2-m10", 2, "Tempat Ibadah Umat Buddha", "mudah", "Tempat ibadah bagi pemeluk agama Buddha adalah ...", ["Vihara", "Masjid", "Gereja", "Pura"], 0, "Vihara adalah rumah ibadah umat Buddha.");

addQ("pan-k2-s01", 2, "Tempat Ibadah Umat Khonghucu", "sedang", "Tempat ibadah bagi pemeluk agama Khonghucu adalah ...", ["Kelenteng / Lithang", "Masjid", "Gereja", "Pura"], 0, "Kelenteng atau Lithang merupakan tempat ibadah pemeluk Khonghucu.");
addQ("pan-k2-s02", 2, "Kitab Suci Agama Islam", "sedang", "Kitab suci bagi pemeluk agama Islam adalah ...", ["Al-Qur'an", "Alkitab (Injil)", "Weda", "Tripitaka"], 0, "Al-Qur'an adalah kitab suci umat Islam.");
addQ("pan-k2-s03", 2, "Kitab Suci Agama Kristen", "sedang", "Kitab suci bagi pemeluk agama Kristen dan Katolik adalah ...", ["Alkitab", "Al-Qur'an", "Weda", "Sishu Wujing"], 0, "Alkitab merupakan kitab suci umat Kristen dan Katolik.");
addQ("pan-k2-s04", 2, "Kitab Suci Agama Hindu", "sedang", "Kitab suci bagi pemeluk agama Hindu adalah ...", ["Weda", "Alkitab", "Al-Qur'an", "Tripitaka"], 0, "Weda adalah kitab suci pemeluk agama Hindu.");
addQ("pan-k2-s05", 2, "Kitab Suci Agama Buddha", "sedang", "Kitab suci bagi pemeluk agama Buddha adalah ...", ["Tripitaka", "Weda", "Alkitab", "Al-Qur'an"], 0, "Tripitaka adalah kitab suci umat Buddha.");
addQ("pan-k2-s06", 2, "Hari Raya Idul Fitri", "sedang", "Hari raya keagamaan Idul Fitri dan Idul Adha dirayakan oleh pemeluk agama ...", ["Islam", "Kristen", "Hindu", "Buddha"], 0, "Idul Fitri dan Idul Adha adalah hari raya umat Islam.");
addQ("pan-k2-s07", 2, "Hari Raya Natal", "sedang", "Hari raya keagamaan memperingati kelahiran Yesus Kristus (Natal) dirayakan oleh pemeluk agama ...", ["Kristen dan Katolik", "Islam", "Hindu", "Khonghucu"], 0, "Natal dirayakan setiap 25 Desember oleh umat Kristiani.");
addQ("pan-k2-s08", 2, "Hari Raya Nyepi", "sedang", "Hari raya Nyepi dan upacara Ngaben merupakan tradisi keagamaan pemeluk agama ...", ["Hindu", "Islam", "Kristen", "Buddha"], 0, "Nyepi dirayakan oleh umat Hindu di Indonesia, khususnya di Bali.");
addQ("pan-k2-s09", 2, "Hari Raya Waisak", "sedang", "Hari raya keagamaan Waisak dirayakan oleh pemeluk agama ...", ["Buddha", "Islam", "Kristen", "Hindu"], 0, "Waisak dirayakan oleh umat Buddha, sering dipusatkan di Candi Borobudur.");
addQ("pan-k2-s10", 2, "Hari Raya Tahun Baru Imlek", "sedang", "Tahun Baru Imlek merupakan perayaan tradisi dan keagamaan bagi pemeluk agama ...", ["Khonghucu", "Islam", "Kristen", "Hindu"], 0, "Imlek adalah perayaan tahun baru bagi umat Khonghucu dan warga Tionghoa.");
addQ("pan-k2-s11", 2, "Mengenal Rumah Adat", "sedang", "Rumah Gadang dengan atap melengkung menyerupai tanduk kerbau berasal dari daerah ...", ["Sumatera Barat (Minangkabau)", "Jawa Barat", "Papua", "Kalimantan Barat"], 0, "Rumah Gadang adalah rumah adat suku Minangkabau di Sumatera Barat.");
addQ("pan-k2-s12", 2, "Rumah Adat Tongkonan", "sedang", "Rumah adat Tongkonan dengan atap berbentuk perahu berasal dari suku Toraja di provinsi ...", ["Sulawesi Selatan", "Sumatera Utara", "Jawa Timur", "Bali"], 0, "Tongkonan adalah rumah adat kebanggaan suku Toraja, Sulawesi Selatan.");
addQ("pan-k2-s13", 2, "Rumah Adat Joglo", "sedang", "Rumah adat tradisional dengan pendopo luas yang berasal dari suku Jawa adalah rumah ...", ["Joglo", "Honai", "Gadang", "Tongkonan"], 0, "Joglo adalah rumah adat khas suku Jawa di Jawa Tengah, DIY, dan Jawa Timur.");
addQ("pan-k2-s14", 2, "Rumah Adat Honai", "sedang", "Rumah adat Honai dengan dinding kayu melingkar dan atap jerami jerami berasal dari daerah ...", ["Papua", "Aceh", "Bali", "Kalimantan"], 0, "Honai adalah rumah tradisional suku di pegunungan Papua.");
addQ("pan-k2-s15", 2, "Menghargai Pakaian Adat", "sedang", "Pada peringatan Hari Kartini di sekolah, murid-murid mengenakan berbagai pakaian adat daerah. Sikap yang patut ditunjukkan adalah ...", ["Bangga dan mengagumi keindahan pakaian adat nusantara", "Mengejek pakaian adat daerah lain", "Menolak memakai pakaian adat", "Menertawakan teman"], 0, "Keberagaman pakaian adat memperkaya khazanah kebudayaan bangsa.");
addQ("pan-k2-s16", 2, "Aturan Bermain Bersama Tetangga", "sedang", "Saat bermain sepeda bersama anak-anak tetangga pada sore hari, aturan yang harus kita taati adalah ...", ["Pulang ke rumah sebelum waktu magrib/petang tiba", "Bermain sampai tengah malam", "Mengayuh sepeda di tengah jalan raya ramai", "Merusak pagar rumah orang"], 0, "Menaati batas waktu bermain menjaga keselamatan dan ketenangan keluarga.");
addQ("pan-k2-s17", 2, "Saling Menghargai di Lingkungan Rumah", "sedang", "Jika ada tetangga yang sedang berduka karena salah satu keluarganya meninggal dunia, tindakan keluarga kita sebaiknya ...", ["Melayat, menyampaikan belasungkawa, dan membantu keluarga yang berduka", "Memutar musik dengan volume keras", "Mengadakan pesta kembang api", "Pura-pura tidak peduli"], 0, "Melayat dan berbela sungkawa mempererat solidaritas kemanusiaan antartetangga.");
addQ("pan-k2-s18", 2, "Musyawarah di Rumah", "sedang", "Ayah, ibu, dan anak-anak berkumpul di ruang tamu untuk menentukan tempat rekreasi keluarga saat liburan. Kegiatan ini dinamakan ...", ["Musyawarah keluarga", "Perdebatan", "Pemungutan denda", "Sidang pengadilan"], 0, "Musyawarah keluarga mengajarkan demokrasi sejak dari lingkungan terdekat.");
addQ("pan-k2-s19", 2, "Sikap Menerima Hasil Keputusan", "sedang", "Jika usul rekreasi kita tidak terpilih dalam musyawarah keluarga, sikap yang baik adalah ...", ["Menerima keputusan bersama dengan lapang dada dan gembira", "Merajuk dan mogok makan", "Memarahi adik", "Mengunci diri di kamar"], 0, "Berjiwa besar menerima hasil musyawarah adalah cerminan kedewasaan moral.");
addQ("pan-k2-s20", 2, "Hak Mendapat Kasih Sayang", "sedang", "Mendapatkan tempat tinggal yang layak, makanan bergizi, dan kasih sayang orang tua di rumah merupakan contoh ... anak.", ["Hak", "Kewajiban", "Hukuman", "Tugas piket"], 0, "Kasih sayang dan perlindungan adalah hak dasar setiap anak.");

addQ("pan-k2-u01", 2, "Hubungan Simbol Rantai dan Kemanusiaan", "sulit", "Mata rantai pada lambang sila kedua terdiri dari bentuk lingkaran dan persegi. Mata rantai tersebut saling mengait tanpa putus yang melambangkan ...", ["Persatuan dan saling membantu antara laki-laki dan perempuan", "Kekuatan rantai besi", "Alat penarik gerobak", "Hiasan dinding"], 0, "Mata rantai bulat (wanita) dan persegi (pria) saling mengait melambangkan hubungan manusia yang bersatu.");
addQ("pan-k2-u02", 2, "Makna Akar Gantung Pohon Beringin", "sulit", "Pohon beringin memiliki sulur dan akar gantung yang menjalar ke berbagai arah, namun bersumber dari satu pohon yang sama. Hal ini melambangkan ...", ["Keberagaman suku bangsa Indonesia yang bersatu di bawah naungan NKRI", "Banyaknya jenis ulat di pohon", "Pohon yang rindang untuk berteduh monyet", "Hutan rimba"], 0, "Pohon beringin melambangkan Indonesia sebagai tempat berteduh seluruh ragam suku bangsa.");
addQ("pan-k2-u03", 2, "Makna Karakter Banteng pada Sila Ke-4", "sulit", "Banteng dipilih sebagai lambang sila keempat Pancasila karena banteng memiliki sifat alami ...", ["Suka berkumpul dan hidup bersama secara sosial", "Suka menyeruduk musuh", "Suka tidur di kubangan", "Sangat liar dan buas"], 0, "Banteng adalah hewan sosial yang suka berkumpul, melambangkan rakyat yang bermusyawarah.");
addQ("pan-k2-u04", 2, "Dilema Menaati Aturan Antrean", "sulit", "Saat Doni sedang mengantre di kasir toko buku, temannya datang dan meminta Doni menyelipkan tempatnya di antrean depan. Sikap Doni yang paling tepat adalah ...", ["Menolak dengan sopan dan meminta temannya mengantre dari belakang", "Mengizinkan temannya memotong antrean", "Ikut menyuruh orang lain mengalah", "Marah dan meninggalkan toko"], 0, "Menolak kecurangan dengan santun menegakkan prinsip keadilan dan ketertiban umum.");
addQ("pan-k2-u05", 2, "Analisis Keseimbangan Hak dan Kewajiban", "sulit", "Setiap anak berhak mendapatkan nilai hasil belajar di sekolah. Agar mendapatkan hak tersebut, kewajiban yang harus dipenuhi murid adalah ...", ["Belajar tekun dan mengerjakan tugas atau ujian dengan jujur", "Hanya menuntut guru memberi nilai 100", "Bermain terus tanpa belajar", "Mencontek pekerjaan teman"], 0, "Hak dan kewajiban harus dilaksanakan secara seimbang.");
addQ("pan-k2-u06", 2, "Kewajiban Menjaga Kebersihan Sungai", "sulit", "Warga desa sepakat membuat aturan larangan membuang sampah ke aliran sungai. Jika ada oknum yang melanggar aturan ini, dampak buruk yang dirasakan seluruh warga adalah ...", ["Aliran air tersumbat dan berpotensi menimbulkan bencana banjir", "Sungai menjadi jernih berkilau", "Ikan di sungai bertambah banyak", "Air sungai menjadi harum"], 0, "Membuang sampah ke sungai merugikan kepentingan dan keselamatan umum.");
addQ("pan-k2-u07", 2, "Menghadapi Teman Berbeda Keyakinan Berpuasa", "sulit", "Saat bulan Ramadhan tiba, Wayan yang beragama Hindu melihat Salman sedang berpuasa. Tindakan Wayan yang mencerminkan toleransi tinggi adalah ...", ["Tidak makan dan minum di depan Salman secara mencolok untuk menghormatinya", "Menyuruh Salman membatalkan puasa", "Makan es krim sambil menggoda Salman", "Mengejek Salman yang lapar"], 0, "Toleransi diwujudkan dengan menjaga tenggang rasa terhadap ibadah orang lain.");
addQ("pan-k2-u08", 2, "Makna Semboyan Bhinneka Tunggal Ika Sehari-hari", "sulit", "Meskipun murid-murid di sekolah berasal dari berbagai latar belakang suku, bahasa, dan agama yang beraneka ragam, mereka tetap hidup rukun berdampingan. Sikap ini adalah perwujudan semboyan ...", ["Bhinneka Tunggal Ika", "Tut Wuri Handayani", "Ing Ngarso Sung Tulodo", "Gemah Ripah Loh Jinawi"], 0, "Bhinneka Tunggal Ika menekankan persatuan di tengah keanekaragaman.");
addQ("pan-k2-u09", 2, "Adab Menghargai Pendapat Berbeda dalam Rapat", "sulit", "Dalam pemilihan ketua kelas 2, Ali dan Budi memiliki ide yang berbeda tentang jadwal piket. Sikap yang benar saat teman menyampaikan pendapatnya adalah ...", ["Mendengarkan sampai selesai tanpa memotong pembicaraan", "Meneriaki dan menyorakinya", "Keluar dari ruangan kelas", "Memaksa guru langsung setuju dengan ide sendiri"], 0, "Mendengarkan pendapat orang lain dengan seksama merupakan etika dasar musyawarah.");
addQ("pan-k2-u10", 2, "Menghindari Sikap Pilih Kasih", "sulit", "Sebagai ketua kelompok belajar, Lisa membagikan lembar kerja kepada semua anggota kelompok tanpa membeda-bedakan suku atau tingkat kekayaan. Tindakan Lisa mencerminkan pengamalan sila ke- ...", ["Lima (Keadilan sosial)", "Satu", "Tiga", "Empat"], 0, "Sila ke-5 menuntut perlakuan adil tanpa diskriminasi kepada sesama.");
addQ("pan-k2-u11", 2, "Perilaku Sesuai Sila Ke-1 di Rumah", "sulit", "Contoh kegiatan keluarga di rumah yang mencerminkan pengamalan sila pertama Pancasila adalah ...", ["Melaksanakan ibadah bersama sesuai ajaran agama masing-masing", "Bermain game online bersama semalaman", "Membeli pakaian mahal bersama-sama", "Menonton bioskop setiap hari"], 0, "Beribadah bersama keluarga memupuk keimanan dan ketakwaan kepada Tuhan YME.");
addQ("pan-k2-u12", 2, "Tenggang Rasa Terhadap Orang Lanjut Usia", "sulit", "Saat naik angkutan umum yang penuh, seorang kakek tua masuk dan tidak mendapat kursi tempat duduk. Tindakan terpuji yang mencerminkan kemanusiaan yang adil dan beradab adalah ...", ["Berdiri dan mempersilakan sang kakek duduk di kursi kita", "Berpura-pura tidur agar tidak melihat sang kakek", "Menertawakan sang kakek yang kelelahan berdiri", "Menyuruh kakek tersebut turun dari angkot"], 0, "Memprioritaskan tempat duduk untuk lansia mencerminkan empati kemanusiaan.");
addQ("pan-k2-u13", 2, "Cinta Produk Dalam Negeri", "sulit", "Ibu membeli sepatu buatan pengrajin lokal Indonesia meskipun di toko terdapat sepatu impor bermerek mahal luar negeri. Sikap ibu mencerminkan pengamalan sila ke- ...", ["Tiga (Persatuan Indonesia)", "Satu", "Dua", "Empat"], 0, "Mencintai dan memakai produk dalam negeri adalah wujud nasionalisme sila ketiga.");
addQ("pan-k2-u14", 2, "Sikap Menghargai Hasil Karya Teman", "sulit", "Ketika pameran hasil prakarya di kelas, karya milik Made mungkin terlihat sangat sederhana dibanding yang lain. Sikap yang pantas kita berikan adalah ...", ["Memberikan pujian atas usahanya dan menyemangatinya", "Merusak hasil karyanya secara diam-diam", "Menertawakan karyanya di depan kelas", "Menyuruh guru membuangnya"], 0, "Menghargai jerih payah karya orang lain mencerminkan sila kelima Pancasila.");
addQ("pan-k2-u15", 2, "Kewajiban Pengendara di Jalan Raya", "sulit", "Lampu pengatur lalu lintas menyala warna merah. Kewajiban setiap pengendara kendaraan bermotor adalah ...", ["Menghentikan kendaraannya di belakang garis marka", "Mempercepat laju kendaraan agar tidak tertangkap", "Membunyikan klakson sekeras-kerasnya", "Berbelok melanggar jalur"], 0, "Menaati rambu lalu lintas menjaga ketertiban dan keselamatan semua pemakai jalan.");
addQ("pan-k2-u16", 2, "Tujuan Pembagian Giliran Piket", "sulit", "Di sekolah dibentuk regu piket dari hari Senin sampai Sabtu. Tujuan utama dibuatnya pembagian piket ini adalah ...", ["Menumbuhkan rasa tanggung jawab bersama menjaga kebersihan kelas", "Menghukum murid-murid tertentu", "Membuat murid kelelahan", "Menggantikan pekerjaan kepala sekolah"], 0, "Piket kelas melatih tanggung jawab bersama dan kebiasaan hidup bersih.");
addQ("pan-k2-u17", 2, "Sikap Saat Tamu Datang ke Rumah", "sulit", "Saat teman orang tua datang berkunjung ke rumah, adab kesopanan anak yang baik adalah ...", ["Membukakan pintu, menyapa dengan hormat, dan mempersilakan masuk", "Langsung membanting pintu kembali", "Meminta uang kepada tamu tersebut", "Bersembunyi sambil berteriak"], 0, "Menerima tamu dengan santun dan ramah mencerminkan adab sopan santun.");
addQ("pan-k2-u18", 2, "Menghargai Keberagaman Alat Musik Tradisional", "sulit", "Angklung adalah alat musik bambu dari Jawa Barat, sedangkan Sasando berasal dari Nusa Tenggara Timur. Sikap kita terhadap kekayaan alat musik daerah ini adalah ...", ["Merasa bangga dan bersemangat untuk mempelajarinya", "Menganggap alat musik daerah kuno dan tidak berguna", "Hanya menyukai musik modern barat", "Menolak mendengarkannya"], 0, "Mempelajari dan melestarikan alat musik daerah adalah kewajiban generasi muda.");
addQ("pan-k2-u19", 2, "Nilai Kejujuran dalam Ujian", "sulit", "Ketika sedang mengerjakan ulangan harian, teman sebangku mengajak kita membuka contekan catatan buku. Tindakan terpuji yang harus kita ambil adalah ...", ["Menolak dengan tegas dan tetap mengerjakan ulangan dengan jujur", "Ikut mencontek karena takut dijauhi", "Memberikan contekan kepada seluruh kelas", "Menyobek lembar jawaban teman"], 0, "Menjaga kejujuran dalam ujian adalah cerminan integritas moral Pancasila.");
addQ("pan-k2-u20", 2, "Mengatasi Perbedaan Pilihan Mainan", "sulit", "Rudi ingin bermain layang-layang di lapangan terbuka, sedangkan Bagas ingin bermain kelereng di teras rumah. Solusi yang adil dan rukun adalah ...", ["Bermain kelereng sebentar di teras lalu bermain layang-layang di lapangan bersama", "Bermusuhan dan saling memukul", "Tidak mau berteman selamanya", "Merusak kelereng dan layang-layang"], 0, "Berkompromi dan saling meluangkan waktu memelihara kerukunan pertemanan.");
addQ("pan-k2-u21", 2, "Tanggung Jawab Meminjam Barang Perpustakaan", "sulit", "Setelah meminjam buku ensiklopedia dari perpustakaan sekolah, kewajiban kita adalah ...", ["Mengembalikan buku tepat waktu dalam kondisi bersih dan tidak robek", "Mencoret-coret halaman buku dengan spidol", "Menjual buku tersebut ke toko loak", "Menyimpannya di rumah selamanya"], 0, "Menjaga keutuhan buku pinjaman merupakan tanggung jawab moral peminjam.");
addQ("pan-k2-u22", 2, "Menolong Korban Bencana Alam", "sulit", "Ketika terjadi musibah gempa bumi di salah satu daerah di Indonesia, murid-murid mengumpulkan pakaian layak pakai dan buku tulis untuk disumbangkan. Kegiatan sosial ini sesuai dengan nilai sila ke- ...", ["Dua (Kemanusiaan yang adil dan beradab)", "Satu", "Empat", "Tiga"], 0, "Membantu meringankan beban korban bencana adalah manifestasi rasa kemanusiaan.");
addQ("pan-k2-u23", 2, "Sikap Bijak Menggunakan Air Bersih", "sulit", "Setelah selesai mencuci tangan di kran sekolah, kita melihat air kran masih mengalir menetes. Sikap yang bertanggung jawab adalah ...", ["Segera memutar kran rapat-rapat agar air bersih tidak terbuang sia-sia", "Membiarkannya meluap sampai banjir", "Bermain ciprat-cipratan air", "Merusak pipa kran"], 0, "Hemat air bersih menjaga kelestarian sumber daya lingkungan hidup.");
addQ("pan-k2-u24", 2, "Tata Tertib Berbicara di Perpustakaan", "sulit", "Di dalam ruang perpustakaan sekolah terdapat aturan larangan bersuara gaduh. Alasan dibuatnya aturan ini adalah ...", ["Agar para pengunjung dapat membaca buku dengan tenang dan konsentrasi", "Agar perpustakaan sepi tidak ada pengunjung", "Supaya petugas perpustakaan bisa tidur", "Agar murid takut datang"], 0, "Ketenangan di perpustakaan mendukung kenyamanan semua pembaca.");
addQ("pan-k2-u25", 2, "Sikap Terhadap Kekalahan Lomba", "sulit", "Regu tarik tambang kelas 2 mengalami kekalahan dalam perlombaan perayaan 17 Agustus. Sikap sportif yang benar adalah ...", ["Memberi selamat kepada regu pemenang dan berlatih lebih giat lagi", "Menuduh wasit berlaku curang tanpa bukti", "Menangis dan melempar tali", "Mengejek tim lawan"], 0, "Sportivitas dan lapang dada menghormati kemenangan orang lain.");
addQ("pan-k2-u26", 2, "Menghormati Perbedaan Bahasa Daerah", "sulit", "Nenek berasal dari daerah Minang dan berbicara dengan intonasi khas daerahnya. Sikap cucu yang berbakti adalah ...", ["Mendengarkan dengan penuh kasih sayang dan santun memahaminya", "Menertawakan logat bicara nenek", "Menolak berbicara dengan nenek", "Menyuruh nenek berbicara bahasa gaul"], 0, "Menghormati orang tua dan keragaman dialek daerah adalah adab mulia.");
addQ("pan-k2-u27", 2, "Menjaga Kerukunan Antarumat Beragama di Desa", "sulit", "Warga desa bergotong royong membersihkan jalan desa yang akan dilewati oleh warga yang hendak menuju tempat ibadah. Kegiatan ini mencerminkan ...", ["Kerukunan hidup dan toleransi antarumat beragama", "Paksaan dari kepala desa", "Pekerjaan yang membuang waktu", "Ketidakadilan warga"], 0, "Gotong royong lintas umat beragama memperkuat keharmonisan bangsa.");
addQ("pan-k2-u28", 2, "Hak Mendapatkan Pendidikan Layak", "sulit", "Setiap anak Indonesia berhak mendapatkan kesempatan bersekolah untuk menuntut ilmu. Hak ini bertujuan agar anak dapat ...", ["Tumbuh menjadi generasi yang cerdas, berilmu, dan berbudi pekerti luhur", "Menjadi orang yang sombong", "Mengalahkan orang tuanya", "Bebas dari aturan masyarakat"], 0, "Pendidikan mencerdaskan kehidupan bangsa dan membentuk karakter anak.");
addQ("pan-k2-u29", 2, "Kewajiban Menjaga Nama Baik Sekolah", "sulit", "Ketika berada di luar lingkungan sekolah mengenakan seragam, murid harus menjaga sikap dan tutur kata karena murid mengemban kewajiban ...", ["Menjaga nama baik dan kehormatan sekolah", "Mencari musuh dari sekolah lain", "Pamer seragam baru", "Berbuat onar di jalan"], 0, "Perilaku murid mencerminkan kualitas pendidikan dan martabat sekolahnya.");
addQ("pan-k2-u30", 2, "Makna Perisai pada Dada Garuda", "sulit", "Perisai yang terdapat pada dada burung Garuda Pancasila melambangkan ...", ["Perjuangan, pertahanan, dan perlindungan diri bangsa Indonesia", "Alat berburu binatang", "Hiasan baju perang kuno", "Mainan pahlawan super"], 0, "Perisai adalah lambang pertahanan dan perlindungan keutuhan bangsa Indonesia.");

