addQ("pan-k3-m01", 3, "Makna Warna Emas Garuda", "mudah", "Warna kuning keemasan pada tubuh burung Garuda Pancasila melambangkan ...", ["Keagungan dan kejayaan bangsa", "Keberanian berperang", "Kesucian hati", "Kesuburan tanah"], 0, "Warna emas melambangkan kebesaran, keagungan, dan kejayaan bangsa Indonesia.");
addQ("pan-k3-m02", 3, "Arah Pandangan Kepala Garuda", "mudah", "Kepala burung Garuda Pancasila menoleh ke arah sebelah ...", ["Kanan", "Kiri", "Bawah", "Atas"], 0, "Kepala Garuda menoleh ke kanan melambangkan kebajikan dan kebaikan.");
addQ("pan-k3-m03", 3, "Pengertian Hak", "mudah", "Sesuatu yang mutlak menjadi milik kita dan penggunaannya tergantung kepada kita dinamakan ...", ["Hak", "Kewajiban", "Sanksi", "Aturan"], 0, "Hak adalah sesuatu yang semestinya kita terima.");
addQ("pan-k3-m04", 3, "Pengertian Kewajiban", "mudah", "Sesuatu yang harus dilakukan dengan penuh tanggung jawab disebut ...", ["Kewajiban", "Hak", "Hadiah", "Pemberian"], 0, "Kewajiban adalah segala hal yang wajib dikerjakan dengan penuh amanah.");
addQ("pan-k3-m05", 3, "Bhinneka Tunggal Ika Asal Kitab", "mudah", "Semboyan Bhinneka Tunggal Ika dipetik dari kitab kuno Sutasoma karya Mpu ...", ["Tantular", "Prapanca", "Sedah", "Walmiki"], 0, "Mpu Tantular menulis semboyan Bhinneka Tunggal Ika dalam Kitab Sutasoma pada zaman Majapahit.");
addQ("pan-k3-m06", 3, "Arti Kata Bhinneka", "mudah", "Kata 'Bhinneka' dalam bahasa Jawa Kuno memiliki arti ...", ["Beraneka ragam / Berbeda-beda", "Satu jua", "Kemenangan", "Kejayaan"], 0, "Bhinneka berasal dari kata 'bhinna' (berbeda) dan 'ika' (itu), artinya berbeda-beda.");
addQ("pan-k3-m07", 3, "Kewajiban Murid di Sekolah", "mudah", "Salah satu kewajiban utama seorang murid saat berada di sekolah adalah ...", ["Menaati tata tertib sekolah dan menghormati bapak ibu guru", "Mendapat nilai rapor bagus tanpa belajar", "Memerintah adik kelas", "Menentukan jam pulang sekolah sendiri"], 0, "Menaati peraturan sekolah dan menghormati guru adalah kewajiban siswa.");
addQ("pan-k3-m08", 3, "Hak Murid di Sekolah", "mudah", "Contoh hak yang semestinya diperoleh murid di lingkungan sekolah adalah ...", ["Mendapatkan bimbingan pelajaran dan pengajaran dari guru", "Mencoret meja kelas sesuka hati", "Membawa mainan mahal ke sekolah", "Datang terlambat tanpa alasan"], 0, "Mendapatkan pengajaran yang bermutu adalah hak setiap murid.");
addQ("pan-k3-m09", 3, "Keputusan Musyawarah Mufakat", "mudah", "Keputusan bersama yang disepakati oleh seluruh peserta musyawarah dinamakan keputusan ...", ["Mufakat", "Voting", "Sepihak", "Diktator"], 0, "Mufakat adalah persetujuan bulat yang dihasilkan dari musyawarah bersama.");
addQ("pan-k3-m10", 3, "Tradisi Sambatan / Gotong Royong", "mudah", "Kegiatan bekerja sama tanpa meminta upah demi kepentingan warga desa dinamakan tradisi ...", ["Gotong royong (kerja bakti)", "Jual beli", "Tukar menukar barang", "Perlombaan"], 0, "Gotong royong adalah warisan luhur gotong royong tanpa pamrih.");

addQ("pan-k3-s01", 3, "Garis Hitam Tebal di Perisai Garuda", "sedang", "Garis hitam tebal melintang di tengah-tengah perisai Garuda melambangkan garis ...", ["Khatulistiwa (ekuator)", "Bujur timur", "Batas negara", "Pantai pulau"], 0, "Garis tebal tersebut melambangkan Indonesia dilintasi garis khatulistiwa.");
addQ("pan-k3-s02", 3, "Pelaksanaan Hak dan Kewajiban", "sedang", "Dalam kehidupan sehari-hari, kita hendaknya mengutamakan pelaksanaan ...", ["Kewajiban terlebih dahulu sebelum menuntut hak", "Hak terlebih dahulu baru kewajiban", "Hanya menuntut hak tanpa kewajiban", "Menolak kedua-duanya"], 0, "Kewajiban harus dipenuhi terlebih dahulu secara bertanggung jawab baru menuntut hak.");
addQ("pan-k3-s03", 3, "Hak Anak di Rumah", "sedang", "Contoh hak seorang anak saat berada di lingkungan rumah keluarga adalah ...", ["Mendapatkan makanan sehat, pakaian, dan ruang belajar", "Mencuci mobil orang tua setiap pagi", "Bebas membentak orang tua", "Tidur seharian tanpa belajar"], 0, "Pemenuhan gizi, pakaian, dan kasih sayang adalah hak anak di rumah.");
addQ("pan-k3-s04", 3, "Kewajiban Anak di Rumah", "sedang", "Contoh kewajiban seorang anak untuk membantu meringankan beban orang tua adalah ...", ["Membantu merapikan kamar sendiri dan belajar tekun", "Menuntut dibelikan ponsel pintar terbaru", "Menonton televisi sampai larut", "Menolak disuruh ibu"], 0, "Merapikan kamar dan mandiri belajar meringankan beban orang tua.");
addQ("pan-k3-s05", 3, "Pemilihan Ketua Kelas Demokratis", "sedang", "Jika musyawarah mufakat belum mencapai titik temu dalam pemilihan ketua kelas, langkah berikutnya yang adil adalah melakukan ...", ["Pemungutan suara terbanyak (voting)", "Penunjukan paksa oleh siswa terkuat", "Mengundi dengan melempar koin", "Membatalkan pemilihan"], 0, "Voting adalah cara demokratis menentukan keputusan jika mufakat tidak tercapai.");
addQ("pan-k3-s06", 3, "Penerimaan Hasil Voting", "sedang", "Setelah pemungutan suara selesai dan calon lain terpilih menjadi ketua kelas, sikap kita yang berjiwa besar adalah ...", ["Menerima dan mendukung ketua kelas terpilih demi kebaikan kelas", "Membuat kerusuhan di kelas", "Menolak menjalankan piket kelas", "Menghasut teman untuk membenci ketua kelas"], 0, "Menghargai hasil suara mayoritas adalah sikap ksatria dalam berdemokrasi.");
addQ("pan-k3-s07", 3, "Tarian Adat Saman", "sedang", "Tari Saman yang dilakukan secara serentak dengan gerakan tepuk tangan dan dada yang ritmis berasal dari suku Gayo di provinsi ...", ["Aceh", "Jawa Barat", "Bali", "Sulawesi Tengah"], 0, "Tari Saman adalah tarian tradisional kebanggaan suku Gayo, Aceh.");
addQ("pan-k3-s08", 3, "Tarian Adat Pendet", "sedang", "Tari Pendet dan Tari Kecak yang terkenal hingga mancanegara merupakan tarian tradisional dari daerah ...", ["Bali", "Papua", "Jawa Timur", "Riau"], 0, "Tari Pendet dan Tari Kecak adalah tarian khas daerah Bali.");
addQ("pan-k3-s09", 3, "Tarian Adat Jaipong", "sedang", "Tarian tradisional Jaipong dengan gerakan lincah dan ceria berasal dari masyarakat suku Sunda di ...", ["Jawa Barat", "Nusa Tenggara Barat", "Maluku", "Sumatera Selatan"], 0, "Tari Jaipong diciptakan oleh seniman Jawa Barat.");
addQ("pan-k3-s10", 3, "Tarian Adat Piring", "sedang", "Tari Piring yang dibawakan dengan memegang piring di telapak tangan tanpa terjatuh berasal dari daerah ...", ["Sumatera Barat (Minangkabau)", "Kalimantan Tengah", "Sulawesi Utara", "Jawa Tengah"], 0, "Tari Piring adalah tari tradisional khas Minangkabau, Sumatera Barat.");
addQ("pan-k3-s11", 3, "Tradisi Gugur Gunung", "sedang", "Tradisi kerja bakti gotong royong membangun sarana desa di daerah Jawa sering dinamakan tradisi ...", ["Gugur gunung", "Sekaten", "Ngaben", "Karapan sapi"], 0, "Gugur gunung adalah istilah gotong royong membangun fasilitas desa di Jawa.");
addQ("pan-k3-s12", 3, "Tradisi Rambu Solo", "sedang", "Upacara adat pemakaman jenazah dengan penyembelihan kerbau di suku Toraja disebut upacara ...", ["Rambu Solo", "Ngaben", "Tiwah", "Kasada"], 0, "Rambu Solo adalah upacara adat kematian khas suku Toraja.");
addQ("pan-k3-s13", 3, "Tradisi Ngaben di Bali", "sedang", "Upacara pembakaran jenazah menurut keyakinan umat Hindu di Bali dinamakan upacara ...", ["Ngaben", "Sekaten", "Rambu Solo", "Grebeg Mulud"], 0, "Ngaben adalah upacara kremasi jenazah umat Hindu Bali.");
addQ("pan-k3-s14", 3, "Toleransi Antarsuku di Sekolah", "sedang", "Ketika berdiskusi kelompok, salah satu anggota kelompok memiliki pendapat yang unik berlandaskan kebiasaan daerahnya. Sikap kelompok sebaiknya ...", ["Menghargai pendapat tersebut dan memadukannya secara bijak", "Mengejek tradisi daerahnya", "Mengeluarkannya dari kelompok", "Memarahinya"], 0, "Keberagaman cara pandang memperkaya wawasan bersama.");
addQ("pan-k3-s15", 3, "Tanggung Jawab Pemakaian Sarana Olahraga", "sedang", "Setelah selesai jam pelajaran olahraga, bola sepak dan raket bulu tangkis harus ...", ["Dikembalikan ke ruang alat olahraga dalam keadaan tertata rapi", "Ditinggalkan begitu saja di lapangan", "Dibawa pulang ke rumah siswa", "Dibuang ke selokan"], 0, "Menjaga dan mengembalikan sarana sekolah adalah kewajiban peminjam.");
addQ("pan-k3-s16", 3, "Sikap Rendah Hati Saat Diskusi", "sedang", "Dalam musyawarah kelas, sikap peserta yang baik saat mengajukan usulan adalah ...", ["Menggunakan kalimat yang santun, jelas, dan tidak memaksakan kehendak", "Berbicara sambil memukul meja", "Menyela pembicaraan guru", "Mengejek usul teman lain"], 0, "Kesantunan berbahasa menjaga kelancaran musyawarah.");
addQ("pan-k3-s17", 3, "Kewajiban Penghematan Energi di Sekolah", "sedang", "Saat jam istirahat tiba dan seluruh siswa keluar ke halaman, kewajiban siswa yang keluar terakhir dari ruang kelas adalah ...", ["Mematikan lampu dan kipas angin kelas yang tidak terpakai", "Menyalakan semua perangkat listrik", "Membiarkan pintu terbuka dengan AC menyala", "Membanting saklar"], 0, "Mematikan perangkat listrik yang tidak digunakan wujud kepedulian lingkungan.");
addQ("pan-k3-s18", 3, "Kerukunan Beragama Sila Pertama", "sedang", "Pemerintah menetapkan hari-hari besar berbagai agama sebagai hari libur nasional. Kebijakan ini mencerminkan pengamalan sila ke- ...", ["Satu (Ketuhanan Yang Maha Esa)", "Tiga", "Empat", "Dua"], 0, "Memberikan penghormatan pada hari besar tiap agama wujud pengamalan sila ke-1.");
addQ("pan-k3-s19", 3, "Penerapan Sila Kemanusiaan di Kelas 3", "sedang", "Mengunjungi teman sekelas yang sedang dirawat di rumah sakit karena sakit demam berdarah merupakan wujud pengamalan sila ke- ...", ["Dua (Kemanusiaan yang adil dan beradab)", "Satu", "Empat", "Lima"], 0, "Menjenguk orang sakit mencerminkan kasih sayang dan tenggang rasa kemanusiaan.");
addQ("pan-k3-s20", 3, "Bangga Menggunakan Bahasa Indonesia", "sedang", "Ketika bertemu dengan teman dari berbagai daerah di tanah air, bahasa persatuan yang kita gunakan untuk berkomunikasi adalah ...", ["Bahasa Indonesia", "Bahasa asing barat", "Bahasa isyarat kasar", "Bahasa daerah masing-masing tanpa kompromi"], 0, "Bahasa Indonesia adalah bahasa persatuan yang menyatukan seluruh suku bangsa.");

addQ("pan-k3-u01", 3, "Analisis Hubungan Hak dan Kewajiban Warga Negara", "sulit", "Pak Anton menginginkan jalan di depan rumahnya diaspal mulus oleh pemerintah (hak). Agar hak tersebut dapat diwujudkan negara, kewajiban yang wajib dipenuhi oleh Pak Anton adalah ...", ["Membayar pajak bumi dan bangunan secara taat dan tepat waktu", "Memasang spanduk protes di jalan raya", "Menutup jalan agar tidak dilewati orang", "Menolak membayar pajak"], 0, "Pembangunan fasilitas umum dibiayai dari penerimaan pajak warga negara.");
addQ("pan-k3-u02", 3, "Dilema Musyawarah dan Kepentingan Bersama", "sulit", "Dalam musyawarah penataan taman kelas, usulan Joni agar taman hanya ditanami tanaman kesukaannya ditolak demi menanam tanaman apotek hidup yang bermanfaat bagi seluruh kelas. Sikap Joni yang benar adalah ...", ["Menerima keputusan tersebut karena kepentingan bersama lebih utama daripada kepentingan pribadi", "Marah dan merusak tanaman apotek hidup", "Memusuhi seluruh anggota kelas", "Menolak masuk sekolah esok hari"], 0, "Musyawarah mengutamakan kepentingan umum di atas kepentingan golongan atau individu.");
addQ("pan-k3-u03", 3, "Penyelesaian Konflik Teman Bermain", "sulit", "Dua orang teman terlibat pertengkaran mulut karena berebut raket bulu tangkis di lapangan. Tindakan yang paling bijaksana yang dapat dilakukan oleh teman lainnya adalah ...", ["Melerai mereka dengan tenang dan mengajak mereka berbagi waktu bermain secara bergantian", "Menyoraki agar mereka berkelahi fisik", "Membela salah satu teman yang paling kaya", "Ikut memukul salah satu dari mereka"], 0, "Mendamaikan perselisihan menjaga persatuan dan suasana damai.");
addQ("pan-k3-u04", 3, "Makna Filosofis Sila Ke-5 Keadilan Sosial", "sulit", "Keadilan sosial dalam sila kelima tidak selalu berarti setiap orang mendapatkan jumlah yang sama persis, melainkan ...", ["Mendapatkan sesuai dengan hak, kebutuhan, dan porsi yang semestinya secara adil", "Membagikan semua kekayaan sama rata tanpa memandang kerja", "Hanya orang kaya yang mendapat bagian", "Orang rajin dan malas mendapat upah sama"], 0, "Keadilan proporsional memberikan hak sesuai kebutuhan dan kelayakan.");
addQ("pan-k3-u05", 3, "Tradisi Nganggung di Bangka Belitung", "sulit", "Tradisi 'Nganggung' membawa makanan di atas dulang kuningan tertutup tudung saji ke masjid untuk dimakan bersama-sama mencerminkan nilai ...", ["Kerukunan, kebersamaan, dan kedermawanan sosial", "Pamer kekayaan perabotan rumah", "Pemborosan bahan makanan", "Persaingan antarkeluarga"], 0, "Tradisi Nganggung memupuk silaturahmi dan kedermawanan warga.");
addQ("pan-k3-u06", 3, "Menghargai Keunikan Dialek Daerah", "sulit", "Bahasa Indonesia memiliki aneka ragam logat/dialek kedaerahan (seperti logat Madura, Jawa, Batak, Papua). Keberagaman dialek ini membuktikan bahwa ...", ["Bangsa Indonesia kaya akan variasi budaya dan tutur tutur daerah", "Bahasa Indonesia sulit dipelajari", "Masyarakat Indonesia tidak bersatu", "Harus dihapuskan logat kedaerahan"], 0, "Variasi dialek mencerminkan kekayaan warisan linguistik nusantara.");
addQ("pan-k3-u07", 3, "Kewajiban Menjaga Kelestarian Lingkungan Hidup", "sulit", "Di lingkungan perumahan sering diadakan kerja bakti membersihkan selokan setiap bulan. Warga yang tidak pernah hadir tanpa alasan yang jelas telah melalaikan ...", ["Kewajiban moral menjaga kebersihan dan kesehatan lingkungan bersama", "Hak mendapatkan udara bersih", "Hak memilih ketua RT", "Kebebasan pribadi"], 0, "Kebersihan lingkungan adalah kewajiban kolektif seluruh warga.");
addQ("pan-k3-u08", 3, "Dampak Buruk Sikap Individualis", "sulit", "Sikap seseorang yang hanya mementingkan dirinya sendiri tanpa mempedulikan kesusahan orang lain di sekitarnya disebut sikap ...", ["Individualistis", "Nasionalis", "Patriotis", "Sosialis"], 0, "Individualisme bertentangan dengan semangat gotong royong Pancasila.");
addQ("pan-k3-u09", 3, "Tenggang Rasa Terhadap Anak Berkebutuhan Khusus", "sulit", "Di sekolah inklusi, terdapat siswa penyandang disabilitas fisik yang menggunakan kursi roda. Sikap seluruh warga sekolah yang sesuai sila kedua adalah ...", ["Menyediakan akses ramah kursi roda dan bersikap ramah saling membantu", "Menjauhi dan menjadikannya bahan lelucon", "Melarangnya masuk ke perpustakaan", "Menyuruhnya pindah sekolah"], 0, "Menghormati kesetaraan martabat setiap manusia wujud peradaban luhur.");
